// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(address caller) internal {
        vm.assume(caller != address(0));
        uint64 _number = 1;
        uint64 _timestamp = 2;
        uint256 _basefee = 3;
        bytes32 _hash = bytes32(uint256(4));
        uint64 _sequenceNumber = 5;
        bytes32 _batcherHash = bytes32(uint256(6));
        uint256 _l1FeeOverhead = 7;
        uint256 _l1FeeScalar = 8;
        bool reverted;
        try c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == true);
    }

    function testFuzz_run(address caller) public {
        _run(caller);
    }

    receive() external payable {}
}
